    Coverage      float64 `json:"coverage"`
}

type ReviewDetails struct {
    GoCode      LanguageReview `json:"go_code"`
    TypeScript  LanguageReview `json:"typescript"`
    Database    DatabaseReview `json:"database"`
    Security    SecurityReview `json:"security"`
