```

#### 3. 审查评分机制
```go
// 审查评分算法
func CalculateScore(report *CodeReviewReport) float64 {
    var totalScore float64
    var weights []float64

    // 代码质量评分 (30%)
    qualityScore := calculateQualityScore(report)
    weights = append(weights, 0.3)
    totalScore += qualityScore * 0.3

    // 性能评分 (25%)
    performanceScore := calculatePerformanceScore(report)
    weights = append(weights, 0.25)
    totalScore += performanceScore * 0.25

    // 安全评分 (25%)
    securityScore := calculateSecurityScore(report)
    weights = append(weights, 0.25)
    totalScore += securityScore * 0.25

    // 可维护性评分 (20%)
    maintainabilityScore := calculateMaintainabilityScore(report)
    weights = append(weights, 0.2)
    totalScore += maintainabilityScore * 0.2

    return math.Round(totalScore*100) / 100
}
```

